script.setup:
// regl wraps the scene's WebGL context: one declarative draw command renders
// 400k points of the Aizawa attractor with additive blending.
const mod = await ctx.utils.import("https://esm.sh/regl@2.1.1");
const createREGL = mod.default ?? mod;
const regl = createREGL({ gl: ctx.gl });
const N = 400000, pos = new Float32Array(N * 3), info = new Float32Array(N * 2);
// Integrate the attractor once; each point keeps its place along the orbit (t) and its speed.
let x = 0.1, y = 0, z = 0;
const a = 0.95, b = 0.7, c = 0.6, d = 3.5, e = 0.25, f = 0.1, dt = 0.004;
for (let i = -2000; i < N; i++) {
  const dx = (z - b) * x - d * y, dy = d * x + (z - b) * y;
  const dz = c + a * z - z * z * z / 3 - (x * x + y * y) * (1 + e * z) + f * z * x * x * x;
  x += dx * dt; y += dy * dt; z += dz * dt;
  if (i < 0) continue;
  pos.set([x, z - 0.6, y], i * 3);
  info.set([i / N, Math.min(1, Math.hypot(dx, dy, dz) / 4)], i * 2);
}
const draw = regl({
  vert: `
  precision highp float;
  attribute vec3 position; attribute vec2 info;
  uniform mat4 mvp; uniform float time, flow, size;
  varying float vSpeed, vGlow;
  void main() {
    gl_Position = mvp * vec4(position, 1.0);
    // Bright pulses run along the orbit in integration order.
    vGlow = pow(fract(info.x * 60.0 - time * flow), 8.0);
    vSpeed = info.y;
    gl_PointSize = size * (1.0 + 1.5 * vGlow) / gl_Position.w;
  }`,
  frag: `
  precision highp float;
  uniform vec3 slow, fast; uniform float exposure;
  varying float vSpeed, vGlow;
  void main() {
    vec2 q = gl_PointCoord - 0.5;
    float fall = smoothstep(0.25, 0.0, dot(q, q));
    vec3 col = mix(slow, fast, vSpeed) * (0.25 + 2.0 * vGlow);
    gl_FragColor = vec4(col * fall * exposure, 1.0);
  }`,
  attributes: { position: pos, info },
  uniforms: {
    mvp: regl.prop("mvp"), time: regl.prop("time"), flow: regl.prop("flow"), size: regl.prop("size"),
    slow: regl.prop("slow"), fast: regl.prop("fast"), exposure: regl.prop("exposure"),
  },
  blend: { enable: true, func: { src: "one", dst: "one" } },
  depth: { enable: false },
  primitive: "points",
  count: N,
});
Object.assign(ctx.state, { regl, draw, camera: ctx.utils.createOrbitCamera({ distance: 4.7, theta: 0.5, phi: 1.25 }) });
ctx.publish("points", N);

script.render:
const s = ctx.state, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const model = mat4.fromYRotation(ctx.time * 0.15);
const mvp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 40, 0.1, 50), mat4.multiply(s.camera.getViewMatrix(), model));
// regl caches GL state; the runtime changed some of it since the last frame.
s.regl._refresh();
s.regl.clear({ color: [0.012, 0.012, 0.02, 1], depth: 1 });
s.draw({ mvp, time: ctx.time, flow: u.u_flow, size: u.u_size * h / 900, slow: u.u_slow, fast: u.u_fast, exposure: u.u_exposure });
